const page = await sdk.scheduling.events.list();
// Ack only after the game has successfully handled the event.
if (page.items[0]) await sdk.scheduling.events.ack(page.items[0].eventId);

const ms = sdk.scheduling.remainingMs({ start: '2026-12-01T00:00:00Z',
  end: '2026-12-02T00:00:00Z', instant: false });
console.log(ms);
